//
//  PurpleVideoFixtures.swift
//  damusTests
//
//  The Purple hosted-video API's own wire contract, copied verbatim.
//
//  Every body below is a byte-for-byte copy of a response recorded in
//  `rust/damus-api/tests/fixtures/video_routes.json` in the damus-io/api repo.
//  That fixture was generated by driving the deployed Node/express
//  implementation through supertest and recording status, content type and
//  body bytes; the Rust port's `tests/video_routes.rs` replays it against its
//  own router asserting byte equality. Decoding these same bytes here is what
//  pins the two sides of the wire to each other — a server-side change that
//  moves a field breaks a test on both sides rather than shipping a client that
//  quietly decodes nothing.
//
//  Two details are deliberate and must survive any edit:
//
//  - **The trailing `\n`.** Express writes one; the decoder has to tolerate it.
//  - **The PascalCase `tus_headers` keys.** They are the reason nothing here
//    may be decoded with `keyDecodingStrategy = .convertFromSnakeCase`.
//
//  This file holds no tests. It is shared because the same status bodies are
//  needed by the wire tests and by the `PendingVideo` state-machine tests, and
//  inlining nine of them twice guarantees drift.
//

import Foundation
@testable import damus

