    // MARK: - Building responses

    /// An `application/json` response, as express sends one.
    static func json(_ status: Int, _ body: String) -> PurpleVideoHTTPResponse {
        PurpleVideoHTTPResponse(
            status: status,
            headers: ["Content-Type": "application/json; charset=utf-8"],
            body: Data(body.utf8)
        )
    }

    /// A `text/html` response. Express answers three of the recorded cases this
    /// way, so this is not a hypothetical.
    static func html(_ status: Int, _ body: String) -> PurpleVideoHTTPResponse {
        PurpleVideoHTTPResponse(
            status: status,
            headers: ["Content-Type": "text/html; charset=utf-8"],
            body: Data(body.utf8)
        )
    }

    /// A response with no `Content-Type` at all.
    static func untyped(_ status: Int, _ body: Data) -> PurpleVideoHTTPResponse {
        PurpleVideoHTTPResponse(status: status, body: body)
    }

    // MARK: - Decoded shortcuts

    /// A decoded status, for tests that are about what happens *after* decoding.
    static func status(_ body: String) throws -> PurpleVideoStatus {
        try PurpleVideoWire.status(json(200, body))
    }

    /// A decoded authorization, for the same reason.
    static func authorization(_ body: String = authorize200) throws -> PurpleVideoAuthorization {
        try PurpleVideoWire.authorization(json(200, body))
    }
}
